<svelte:options customElement={{
  props: {
    title: { reflect: true, type: 'String', attribute: 'title' },
    options: { reflect: true, type: 'Array', attribute: 'options' },
    extraBoilerplateText: { reflect: true, type: 'String', attribute: 'extra-boilerplate-text' },
  },
}} />

<script lang="ts" module>
  import type { EntraStaticTenantBranding } from '@shi-institute/schemas';
  import { fetchWithHydration } from '../../utils';

  export interface EntraLikeUIProps {
    title?: string;
    options?: {
      href: string;
      description: string;
      smallDescription: string;
      logoSrc: string;
      padding?: number;
    }[];
    extraBoilerplateText?: string;
  }
</script>

<script lang="ts">
  const {
    title = 'Choose an option to continue',
    options = [
      {
        href: 'https://sonny.furman.edu/idp/profile/SAML2/Unsolicited/SSO?providerId=Furman.maps.arcgis.com',
        description: 'ArcGIS Online for Education',
        smallDescription: 'Use for course-related and research-related GIS hosting.',
        logoSrc:
          'data:image/png;base64,',
        padding: 4,
      },
      {
        href: 'https://sonny.furman.edu/idp/profile/SAML2/Unsolicited/SSO?providerId=gis.furman.edu.portal',
        description: 'ArcGIS Enterprise for Education',
        smallDescription: 'Use for ArcGIS Pro education & research licensing and research-related GIS hosting.',
        logoSrc:
          'data:image/png;base64,',
        padding: 4,
      },
      {
        href: 'https://paladin.maps.arcgis.com/home/signin.html',
        description: 'ArcGIS Online for Administrative Use',
        smallDescription: 'Use for administrative, commercial, and for-profit purposes.',
        logoSrc:
          'data:image/png;base64,',
        padding: 4,
      },
    ],
    extraBoilerplateText = '<p><a href="https://shi.institute/services/" rel="noopener noreferrer">Shi Applied Research</a></p><p><a href="https://gis.furman.edu/sal/" rel="noopener noreferrer">Spatial Analysis Lab</a></p>',
  } = $props() as EntraLikeUIProps;

  const isLocalhost = window.location.hostname === 'localhost';
  const isShiInstitute = window.location.hostname === ('shi.institute');
  const fetcher = await fetchWithHydration<EntraStaticTenantBranding>('static-tenant-branding', () => (!isLocalhost && !isShiInstitute ? 'https://shi.institute' : '') + '/.api/entra/static-tenant-branding');
  
  const illustration = $derived(fetcher.data?.Illustration);
</script>

<main style:--background-color={fetcher.data?.BackgroundColor || '#582c83'}>
  <div
    class="background"
    class:hasIllustration={!!illustration}
    style:--background-color={fetcher.data?.BackgroundColor || '#582c83'}
    style:--background-image={illustration ? `url(${illustration})` : 'none'}
  ></div>

  <article>
    <div class="sign-in-box">
      {#if fetcher.data?.BannerLogo}
        <img id="bannerLogo" src={fetcher.data.BannerLogo} alt="Furman University logo" />
      {:else}
        <img
          id="bannerLogo"
          src="https://aadcdn.msauthimages.net/dbd5a2dd-8izupdnymtm14ovj3ndiqaomjcz5dp57lq9yr5zqjcy/logintenantbranding/0/bannerlogo?ts=639052522391948624"
          alt="Furman University logo"
        />
      {/if}

      {#if fetcher.loading}
        <div id="loginHeader" role="heading" aria-level="1">Please wait</div>
      {:else if fetcher.error}
        <div id="loginHeader" role="heading" aria-level="1">Something went wrong</div>
        <p>Error: {fetcher.error.message}</p>
      {:else if fetcher.data}
        <div id="loginHeader" role="heading" aria-level="1">{title}</div>

        {#each options as { href, description, smallDescription, logoSrc, padding }, index}
          <div id="credentialList" class:last={index === options.length - 1}>
            <a class="tile" {href}>
              <img class="tile-img" role="presentation" src={logoSrc} alt="" style:--padding={(padding || 0) + 'px'} />
              <div class="tile-content">
                <div class="description">{description}</div>
                <div><small>{smallDescription}</small></div>
              </div>
            </a>
          </div>
        {/each}

        <div class="buttons">
          <button onclick={() => history.back()}>Back</button>
        </div>
      {/if}

      {#if fetcher.data?.BoilerPlateText}
        <div id="idBoilerPlateText">
          {@html fetcher.data.BoilerPlateText.replaceAll('target="_blank"', '')}
          {@html extraBoilerplateText}
        </div>
      {/if}
    </div>
  </article>
</main>

